        if matrix[0][j]==0: r0=True;break
    for i in range(m):
        if matrix[i][0]==0: c0=True;break
    for i in range(1,m):
        for j in range(1,n):
            if matrix[i][j]==0: matrix[i][0]=matrix[0][j]=0
    for i in range(1,m):
