def isValidSudoku(board):
    rows=[set() for _ in range(9)]
    cols=[set() for _ in range(9)]
    boxs=[set() for _ in range(9)]
    for i in range(9):
        for j in range(9):
            v=board[i][j]
            if v=='.': continue
            bi=(i//3)*3+(j//3)
            if v in rows[i] or v in cols[j] or v in boxs[bi]:
                return False
            rows[i].add(v);cols[j].add(v);boxs[bi].add(v)
    return True

